mkdir -p /tmp/probe/format-flag/model && cat > /tmp/probe/format-flag/model/main.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"sort"
)

// model of goimports-reviser -format on a file that needs no import reordering
func gofmtSrc(src []byte) ([]byte, error) { return format.Source(src) }

func insertBlanks(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "a.go", src, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	type ins struct{ offset int }
	var offsets []int
	for i := 1; i < len(f.Decls); i++ {
		prev := f.Decls[i-1]
		cur := f.Decls[i]
		prevEndLine := fset.Position(prev.End()).Line
		curPosLine := fset.Position(cur.Pos()).Line
		// skip if a comment lies between prev.End() and cur.Pos()
		hasComment := false
		for _, cg := range f.Comments {
			for _, c := range cg.List {
				if c.Pos() > prev.End() && c.End() < cur.Pos() {
					hasComment = true
				}
			}
		}
		_ = hasComment
		if hasComment {
			continue
		}
		if curPosLine == prevEndLine+1 {
			// insert newline at start of cur's line
			off := fset.Position(cur.Pos()).Offset
			// walk back to beginning of line
			for off > 0 && src[off-1] != '\n' {
				off--
			}
			offsets = append(offsets, off)
		}
	}
	sort.Sort(sort.Reverse(sort.IntSlice(offsets)))
	out := src
	for _, off := range offsets {
		var b bytes.Buffer
		b.Write(out[:off])
		b.WriteByte('\n')
		b.Write(out[off:])
		out = b.Bytes()
	}
	_ = ast.Print
	return out, nil
}

func main() {
	doFormat := len(os.Args) > 2 && os.Args[2] == "format"
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	out, err := gofmtSrc(src)
	if err != nil {
		fmt.Fprintln(os.Stderr, "pass1:", err)
		os.Exit(1)
	}
	if doFormat {
		out, err = insertBlanks(out)
		if err != nil {
			fmt.Fprintln(os.Stderr, "insert:", err)
			os.Exit(1)
		}
	}
	out2, err := gofmtSrc(out)
	if err != nil {
		fmt.Fprintln(os.Stderr, "pass2:", err)
		os.Exit(1)
	}
	os.Stdout.Write(out2)
}
EOF
